"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["86084"],{933575(e){e.exports=JSON.parse('{"id":14156,"title":"\u624B\u7ED8\u6D82\u9E26 \u77E5\u8BC6\u5361\u7247","description":"\u6839\u636E\u4E0B\u9762\u8FD9\u6BB5\u89C6\u9891\u7684\u6587\u5B57\u6458\u8981\uFF0C\u751F\u6210\u4E00\u5F20\u624B\u7ED8\u6D82\u9E26\u98CE\u683C\u7684\u8BFB\u4E66\u7B14\u8BB0\u4FE1\u606F\u56FE\u3002 \u6458\u8981\u5982\u4E0B\uFF1A \u6807\u9898\uFF1A\u201C\u5FAE\u4E60\u60EF\u5982\u4F55\u5F7B\u5E95\u6539\u53D8\u4EBA\u751F\u201D \u201C\u8D85\u7EA7\u61D2\u4EBAStephen Guise\u4ECE\u6BCF\u59291\u4E2A\u4FEF\u5367\u6491\u5F00\u59CB\uFF0C\u56E0\u76EE\u6807\u6613\u5B8C\u6210\u800C\u80FD\u575A\u6301\uFF0C\u9010\u6E10\u4E0D\u6EE1\u8DB3\u53EA\u505A1\u4E2A\uFF0C\u6700\u7EC8\u8EAB\u6750\u53D8\u597D\u3001\u6212\u9664\u62D6\u5EF6\uFF0C\u5C06\u7ECF\u5386\u5199\u6210\u300A\u5FAE\u4E60\u60EF\u300B\u7545\u9500\u4E66\uFF0C\u5F71\u54CD\u5343\u4E07\u4EBA\u3002\u201D \u4FE1\u606F\u56FE\u4E25\u683C\u9075\u5FAA\u4EE5\u4E0B\u98CE\u683C: 1.\u6574\u4F53\u98CE\u683C\u4E0E\u5A92\u4ECB:\u91C7\u7528\u5145\u6EE1\u6D3B\u529B\u7684\u624B\u7ED8\u6D82\u9E26\u7B14\u8BB0(Sketchnote)\u98CE\u683C\uFF0C\u4E13\u4E1A\u77E5\u8BC6\u7B14\u8BB0\u7684\u5B66\u9738\u98CE\u683C\uFF0C\u4E0D\u8981\u592A\u5361\u901A\u3002\u9ED1\u8272\u4F7F\u7528\u6DF1\u68D5\u3001\u6A59\u9EC4\u6216\u6D77\u519B\u84DD\uFF0C\u8F7B\u5FAE\u6C34\u5F69\u8FDB\u884C\u586B\u8272\uFF0C\u5E76\u642D\u914D\u67D4\u548C\u7684\u9ED1\u8272\u6216\u6DF1\u68D5\u8272\u7EC6\u7EBF\u7B49\u52FE\u52D2\u8F6E\u5ED3\u3002\u7AD6\u7248(3:4) \u6784\u56FE\u3002 2.\u914D\u8272\u65B9\u6848(\u5173\u952E): \u6574\u5F20\u56FE\u90FD\u5E94\u8BE5\u662F\u5F69\u8272\u7684\uFF0C\u91C7\u7528\u660E\u4EAE\u3001\u6E05\u65B0\u3001\u548C\u8C10\u7684\u8272\u5F69\u7EC4\u5408(\u6D77\u519B\u84DD#1E3A8A\u3001\u6D45\u84DD#60A5FA\u3001\u91D1\u8272#F59E0B\u3001\u5976\u6CB9\u8272\u80CC\u666F#FEFCE8) \u80CC\u666F\u5E94\u6709\u6DE1\u6DE1\u7EB8\u5F20\u7EB9\u7406\u7684\u7C73\u8272\uFF0C\u6216\u8005\u76F4\u63A5\u7559\u767D\uFF0C\u4F46\u753B\u9762\u4E3B\u4F53\u5FC5\u987B\u662F\u4E94\u5F69\u6591\u6593\u7684\u3002 \u989C\u8272\u586B\u5145\u5E94\u6A21\u4EFF\u5F69\u94C5\u6216\u6C34\u5F69\u7684\u8D28\u611F\uFF0C\u5E26\u6709\u81EA\u7136\u7684\u7B14\u89E6\u611F\uFF0C\u800C\u4E0D\u662F\u5747\u5300\u7684\u6570\u5B57\u5E73\u6D82\u3002 3.\u7EBF\u6761\u7279\u5F81:\u6240\u6709\u8F6E\u5ED3\u7EBF\u90FD\u5FC5\u987B\u662F\u4E0D\u5B8C\u7F8E\u3001\u7565\u5E26\u6296\u52A8\u7684\u624B\u7ED8\u7EBF\u6761\uFF0C\u7ED9\u4EBA\u4E00\u79CD\u67D4\u8F6F\u3001\u4EB2\u5207\u7684\u611F\u89C9\u3002 4.\u5B57\u4F53\u98CE\u683C: \u6240\u6709\u6587\u5B57\u90FD\u5FC5\u987B\u662F\u5F69\u8272\u7684\u624B\u5199\u4F53\uFF0C\u7EDD\u5BF9\u4E0D\u8981\u4F7F\u7528\u4EFB\u4F55\u7535\u8111\u5B57\u4F53\u3002 \u6587\u5B57\u7684\u989C\u8272\u53EF\u4EE5\u4E0E\u5B83\u6240\u63CF\u8FF0\u7684\u63D2\u56FE\u989C\u8272\u76F8\u547C\u5E94\uFF0C\u6216\u8005\u4F7F\u7528\u7EDF\u4E00\u7684\u6DF1\u8272(\u5982\u6DF1\u84DD\u3001\u6DF1\u68D5)\u4EE5\u4FDD\u8BC1\u53EF\u8BFB\u6027\u3002 \u6807\u9898\u548C\u5173\u952E\u8BCD:\u4F7F\u7528\u52A0\u7C97\u7684\u3001\u6216\u5E26\u6709\u7B80\u5355\u8FB9\u6846\u7684\u624B\u5199\u827A\u672F\u5B57\u6765\u7A81\u51FA\u3002 \u6B63\u6587\u548C\u6CE8\u91CA:\u4F7F\u7528\u6E05\u6670\u3001\u81EA\u7136\u7684\u4E2A\u4EBA\u7B14\u8BB0\u624B\u5199\u4F53\u3002 5.\u63D2\u56FE\u4E0E\u56FE\u6807: \u6240\u6709\u56FE\u5F62\u5143\u7D20\u5FC5\u987B\u662F\u5145\u6EE1\u8272\u5F69\u7684\u3001\u7B80\u5355\u7684\u6D82\u9E26/\u7B80\u7B14\u753B\u98CE\u683C\u3002\u4F7F\u7528\u624B\u7ED8\u7684\u5F69\u8272\u7BAD\u5934\u3001\u6846\u7EBF\u3001\u9879\u76EE\u7B26\u53F7\u548C\u5206\u5272\u7EBF\u6765\u7EC4\u7EC7\u4FE1\u606F\u3002","owner":"Yingzhang Pang","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-07-03T09:56:55.541Z"}')}}]);